def receipt_share_token(receipt_id):
    """Mint (or return existing) share token for a receipt the caller owns."""
    current_user = get_current_user()
    if current_user is None:
        return jsonify({"error": "unauthorized"}), 401

    receipt = UserReceipt.query.filter_by(
        id=receipt_id, user_id=current_user.id, deleted_at=None
    ).first()
    if receipt is None:
        return jsonify({"error": "not_found"}), 404

    token = _ensure_share_token(receipt)
    return jsonify({"share_token": token})


