7	import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
8	import { QRCode } from '@/components/ui/kibo-ui/qr-code';
9	
10	interface ReceiptDetailsCardProps {
11	  merchant: string | null;
12	  date: Date | number | null;
13	}
14	
15	/**
16	 * Receipt details card component that displays merchant and date information.
17	 * Includes a QR code toggle to display the current page URL.
18	 */
19	export const ReceiptDetailsCard = ({
20	  merchant,
21	  date,
22	}: ReceiptDetailsCardProps) => {
23	  const { t, i18n } = useLingui();
24	  const [showQrCode, setShowQrCode] = useState(false);
25	
26	  // Format date - handle both Date objects and timestamps (seconds or milliseconds)
27	  const formatDate = (): string => {
28	    if (!date) return t`Unknown`;
29	
30	    if (date instanceof Date) {
31	      return date.toLocaleDateString(i18n.locale);
32	    }
33	
34	    // Handle numeric timestamp
35	    // Heuristic: If the timestamp is less than Jan 1, 2000 in milliseconds (946684800000),
36	    // assume it's in seconds. This works for any reasonable receipt date.
37	    const timestamp = typeof date === 'number' ? date : 0;
38	    const YEAR_2000_MS = 946684800000;
39	    const dateObj = new Date(
40	      timestamp < YEAR_2000_MS ? timestamp * 1000 : timestamp
41	    );
42	
43	    // Validate the date
44	    if (isNaN(dateObj.getTime())) {
45	      return t`Invalid Date`;
46	    }
47	
48	    return dateObj.toLocaleDateString(i18n.locale);
49	  };
50	
51	  return (
52	    <Card className="overflow-hidden border-0 shadow-[0_2px_12px_0_rgba(0,0,0,0.06)]">
