57	            <Trans>Document Details</Trans>
58	          </CardTitle>
59	          <Button
60	            variant="outline"
61	            size="sm"
62	            onClick={() => setShowQrCode(!showQrCode)}
63	          >
64	            <QrCode className="mr-1 h-4 w-4" />
65	            {showQrCode ? (
66	              <Trans>Hide QR Code</Trans>
67	            ) : (
68	              <Trans>Show QR Code</Trans>
69	            )}
70	          </Button>
71	        </div>
72	      </CardHeader>
73	      <CardContent className="px-4 sm:px-5">
74	        {showQrCode && (
75	          <motion.div
76	            initial={{ opacity: 0, y: 20 }}
77	            animate={{ opacity: 1, y: 0 }}
78	            transition={{ duration: 0.5 }}
79	            className="flex justify-center py-4"
80	          >
81	            <QRCode data={window.location.href} className="h-48 w-48" />
82	          </motion.div>
83	        )}
84	        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-6">
85	          <div className="flex items-center gap-3 overflow-hidden">
86	            <Tag className="h-5 w-5 flex-shrink-0 text-muted-foreground" />
87	            <span className="whitespace-nowrap text-base font-medium">
88	              <Trans>Merchant:</Trans>
89	            </span>
90	            <span className="ml-auto truncate text-base font-semibold">
91	              {merchant || t`Unknown`}
92	            </span>
93	          </div>
94	
95	          <div className="flex items-center gap-3 overflow-hidden">
96	            <Calendar className="h-5 w-5 flex-shrink-0 text-muted-foreground" />
97	            <span className="whitespace-nowrap text-base font-medium">
98	              <Trans>Date:</Trans>
99	            </span>
100	            <span className="ml-auto truncate text-base font-semibold">
101	              {formatDate()}
102	            </span>
