import { useAuth } from '@clerk/clerk-react';
import { Trans, useLingui } from '@lingui/react/macro';
import { motion } from 'framer-motion';
import { Calendar, QrCode, ShoppingBag, Tag } from 'lucide-react';
import { useEffect, useState } from 'react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { QRCode } from '@/components/ui/kibo-ui/qr-code';

interface ReceiptDetailsCardProps {
  receiptId: number | string;
  merchant: string | null;
  date: Date | number | null;
}

const API_URL =
  import.meta.env.REACT_APP_API_URL || 'http://localhost:5000/api';

/**
 * Receipt details card component that displays merchant and date information.
 * Includes a QR code toggle that encodes an unguessable share link
 * (`/r/<share_token>`), minted lazily from the backend.
 */
export const ReceiptDetailsCard = ({
  receiptId,
  merchant,
  date,
}: ReceiptDetailsCardProps) => {
  const { t, i18n } = useLingui();
  const { getToken, isSignedIn } = useAuth();
  const [showQrCode, setShowQrCode] = useState(false);
  const [shareUrl, setShareUrl] = useState<string | null>(null);
  const [shareError, setShareError] = useState<string | null>(null);

  useEffect(() => {
    if (!showQrCode || shareUrl || !isSignedIn) return;
    let cancelled = false;
    (async () => {
      try {
        const token = await getToken();
        const res = await fetch(
          `${API_URL}/receipts/${receiptId}/share-token`,
          {
            method: 'POST',
            headers: token ? { Authorization: `Bearer ${token}` } : {},
          }
        );
        if (!res.ok) throw new Error(`status ${res.status}`);
        const data: { share_token: string } = await res.json();
        if (!cancelled) {
          setShareUrl(`${window.location.origin}/r/${data.share_token}`);
        }
      } catch (err) {
        if (!cancelled) {
          console.error('[ReceiptDetailsCard] share token failed', err);
          setShareError(t`Could not generate share link`);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [showQrCode, shareUrl, isSignedIn, receiptId, getToken, t]);

  // Format date - handle both Date objects and timestamps (seconds or milliseconds)
  const formatDate = (): string => {
    if (!date) return t`Unknown`;

    if (date instanceof Date) {
      return date.toLocaleDateString(i18n.locale);
    }

    // Handle numeric timestamp
    // Heuristic: If the timestamp is less than Jan 1, 2000 in milliseconds (946684800000),
    // assume it's in seconds. This works for any reasonable receipt date.
    const timestamp = typeof date === 'number' ? date : 0;
    const YEAR_2000_MS = 946684800000;
    const dateObj = new Date(
      timestamp < YEAR_2000_MS ? timestamp * 1000 : timestamp
    );

    // Validate the date
    if (isNaN(dateObj.getTime())) {
      return t`Invalid Date`;
    }

    return dateObj.toLocaleDateString(i18n.locale);
  };

  return (
    <Card className="overflow-hidden border-0 shadow-[0_2px_12px_0_rgba(0,0,0,0.06)]">
      <CardHeader className="px-4 pb-2 sm:px-5">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2 font-display text-lg font-semibold">
            <ShoppingBag className="h-5 w-5 text-muted-foreground" />
            <Trans>Document Details</Trans>
          </CardTitle>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowQrCode(!showQrCode)}
          >
            <QrCode className="mr-1 h-4 w-4" />
            {showQrCode ? (
              <Trans>Hide QR Code</Trans>
            ) : (
              <Trans>Show QR Code</Trans>
            )}
          </Button>
        </div>
      </CardHeader>
      <CardContent className="px-4 sm:px-5">
        {showQrCode && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="flex flex-col items-center justify-center py-4"
          >
            {shareUrl ? (
