42	/**
43	 * ZeroProvider wrapper that derives userID from Clerk authentication.
44	 * Uses the authenticated Clerk user ID when available, otherwise falls back
45	 * to a persistent anonymous ID for unauthenticated collaborative sessions.
46	 */
47	export function AuthenticatedZeroProvider({
48	  children,
49	}: {
50	  children: React.ReactNode;
51	}) {
52	  const [token, setToken] = useState<string | null>(null);
53	  const [tokenError, setTokenError] = useState<Error | null>(null);
54	  const [isRetrying, setIsRetrying] = useState(false);
55	  const { userId, isLoaded, getToken } = useAuth();
56	
57	  const fetchToken = useCallback(async () => {
58	    try {
59	      const fetchedToken = await getToken();
60	      if (fetchedToken === null && userId) {
61	        // Clerk session pending/initializing - treat as error
62	        setTokenError(new Error('Session initializing, please retry'));
63	        setToken(null);
64	      } else {
65	        setToken(fetchedToken);
66	        setTokenError(null);
67	      }
68	    } catch (error) {
69	      setTokenError(error as Error);
70	      // For anonymous users, null token is expected, so set it explicitly
71	      // For authenticated users, this is an error state
72	      setToken(null);
73	    } finally {
74	      setIsRetrying(false);
75	    }
76	  }, [getToken, userId]);
77	
78	  useEffect(() => {
79	    if (!isLoaded) {
80	      return;
81	    }
82	
83	    fetchToken();
84	  }, [fetchToken, userId, isLoaded]);
85	
86	  const handleRetry = async () => {
87	    setIsRetrying(true);
88	    await fetchToken();
89	  };
90	
