92	    () => ({
93	      cacheURL: ZERO_CACHE_URL,
94	      queryURL: ZERO_QUERY_URL,
95	      mutateURL: ZERO_MUTATE_URL,
96	      schema,
97	      mutators,
98	      // Use Clerk user ID when authenticated, otherwise use persistent anonymous ID
99	      userID: userId ?? getAnonymousUserID(),
100	      auth: token,
101	      context: {
102	        userID: userId ?? null,
103	      },
104	    }),
105	    [userId, token]
106	  );
107	
108	  // Don't render Zero until Clerk has loaded to avoid creating a Zero instance
109	  // with an anonymous ID that immediately switches to an authenticated ID.
110	  // For authenticated users, also wait for token. Anonymous users can proceed with null token.
111	  if (!isLoaded || (userId && !token && !tokenError)) {
112	    return (
113	      <div className="flex min-h-screen items-center justify-center">
114	        <Spinner className="size-8" />
115	      </div>
