131	              <Trans>
132	                Failed to fetch authentication token. Your requests may not be
133	                properly authenticated.
134	              </Trans>
135	            </p>
136	            {tokenError.message && (
137	              <p className="mb-4 text-xs opacity-80">{tokenError.message}</p>
138	            )}
