@receipts_bp.route("/api/health", methods=["GET"])
def health_check():
    """Simple health check endpoint"""
    return jsonify({"status": "healthy"})


def _ensure_share_token(receipt):
    """Mint and persist a share token on the receipt if it doesn't have one.

    Returns the token. The unique index on share_token guards against the
    astronomically unlikely collision; on conflict we retry once.
    """
    if receipt.share_token:
        return receipt.share_token
    for _ in range(2):
        receipt.share_token = secrets.token_urlsafe(16)
        try:
            db.session.commit()
            return receipt.share_token
        except IntegrityError:
            db.session.rollback()
            receipt.share_token = None
    raise RuntimeError("failed to mint unique share token")


@receipts_bp.route("/api/receipts/<int:receipt_id>/share-token", methods=["POST"])
def receipt_share_token(receipt_id):
    """Mint (or return existing) share token for a receipt the caller owns."""
    current_user = get_current_user()
    if current_user is None:
        return jsonify({"error": "unauthorized"}), 401

    receipt = UserReceipt.query.filter_by(
        id=receipt_id, user_id=current_user.id, deleted_at=None
    ).first()
    if receipt is None:
        return jsonify({"error": "not_found"}), 404

    token = _ensure_share_token(receipt)
    return jsonify({"share_token": token})


@receipts_bp.route("/api/receipts/preview/<token>", methods=["GET"])
@limiter.limit("60 per minute; 600 per hour")
def receipt_preview(token):
    """Public minimal receipt fields for link-preview (Open Graph) generation.

    Keyed by unguessable share token — sequential ID enumeration is no longer
    possible. Exposes only merchant, date, and total.
    """
    if not token or len(token) > 32:
        return jsonify({"error": "not_found"}), 404

    receipt = UserReceipt.query.filter_by(share_token=token, deleted_at=None).first()
    if receipt is None:
        return jsonify({"error": "not_found"}), 404

    response = jsonify(
        {
            "merchant": receipt.merchant,
            "date": receipt.date.isoformat() if receipt.date else None,
            "total": float(receipt.total) if receipt.total is not None else None,
        }
    )
    response.headers["Cache-Control"] = "public, max-age=300, s-maxage=3600"
    return response

