def _ensure_share_token(receipt):
    """Mint and persist a share token on the receipt if it doesn't have one.

    Returns the token. The unique index on share_token guards against the
    astronomically unlikely collision; on conflict we retry once.
    """
    if receipt.share_token:
        return receipt.share_token
    for _ in range(2):
        receipt.share_token = secrets.token_urlsafe(16)
        try:
            db.session.commit()
            return receipt.share_token
        except IntegrityError:
            db.session.rollback()
            receipt.share_token = None
    raise RuntimeError("failed to mint unique share token")


